using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using XeoTechErp.Api.Data;using XeoTechErp.Api.Models;
namespace XeoTechErp.Api.Controllers.Invoices;
[ApiController,Route("api/invoices"),Authorize]
public class InvoicesController(XeoTechDbContext db):ControllerBase{
[HttpGet]public async Task<IActionResult> Get([FromQuery]InvoiceStatus? status){var q=db.Invoices.AsNoTracking().Include(x=>x.Customer).Include(x=>x.Order).AsQueryable();if(status.HasValue)q=q.Where(x=>x.Status==status);return Ok(await q.OrderByDescending(x=>x.Issued).ToListAsync());}
[HttpGet("{id:int}")]public async Task<IActionResult> GetById(int id)=>Ok(await db.Invoices.AsNoTracking().Include(x=>x.Customer).Include(x=>x.Order).FirstOrDefaultAsync(x=>x.Id==id)??(object)new{error="Invoice not found"});
[HttpPost("from-order/{orderId:int}")]public async Task<IActionResult> Create(int orderId){var o=await db.Orders.Include(x=>x.Customer).FirstOrDefaultAsync(x=>x.Id==orderId);if(o is null)return NotFound();if(o.Status!=OrderStatus.Delivered)return Conflict(new{error="Invoice can only be created for delivered orders."});if(await db.Invoices.AnyAsync(x=>x.OrderId==orderId))return Conflict(new{error="Invoice already exists."});var days=o.Customer.PaymentTerms switch{"Due on Receipt"=>0,"Net 15"=>15,"Net 45"=>45,"Net 60"=>60,_=>30};var i=new Invoice{OrderId=o.Id,CustomerId=o.CustomerId,CustomerName=o.Customer.Company,Amount=o.Total,Issued=DateTime.UtcNow,Due=DateTime.UtcNow.AddDays(days)};db.Invoices.Add(i);await db.SaveChangesAsync();return CreatedAtAction(nameof(GetById),new{id=i.Id},i);}
[HttpPost("{id:int}/pay")]public async Task<IActionResult> Pay(int id){var i=await db.Invoices.FindAsync(id);if(i is null)return NotFound();i.Status=InvoiceStatus.Paid;i.PaidOn=DateTime.UtcNow;if(i.OrderId is int oid){var o=await db.Orders.FindAsync(oid);if(o is not null){var paid=await db.Payments.Where(x=>x.OrderId==oid).SumAsync(x=>(decimal?)x.Amount)??0;if(paid<i.Amount)db.Payments.Add(new Payment{OrderId=oid,Amount=i.Amount-paid,Method=PaymentMethod.Other});}}await db.SaveChangesAsync();return Ok(i);}
}